        q: '네트워크 주소와 브로드캐스트 주소는 왜 호스트에서 빼나요?',
        a: '네트워크 주소(호스트 비트가 모두 0)는 서브넷 자체를 가리키고, 브로드캐스트 주소(호스트 비트가 모두 1)는 해당 네트워크의 모든 장비에 동시에 보내는 용도라 개별 장비에 할당할 수 없습니다. 그래서 사용가능 호스트 수 = 전체 주소 − 2 입니다.',
