      '정렬(pretty) 모드는 들여쓰기 2칸·4칸을 선택할 수 있고, 압축(minify) 모드는 모든 공백을 없애 한 줄로 만듭니다.',
      '입력 크기·출력 크기(바이트)와 중첩 포함 전체 키 개수를 통계로 보여줘 압축 효과를 한눈에 확인합니다.',
      '결과를 복사하거나 formatted.json 파일로 내려받을 수 있고, 샘플 버튼으로 예시 JSON 을 바로 불러옵니다.',
      '모든 파싱·변환이 브라우저 안에서 처리돼 데이터가 서버로 전송되지 않습니다.',
