    metaDescription:
      'UUID v4 를 1개부터 최대 1만 개까지 한 번에 생성합니다. crypto.randomUUID 기반, 대문자·하이픈 제거·중괄호 포맷 선택, 전체 복사·TXT 다운로드. 테스트 데이터·기본키·식별자 생성에 쓰는 무료 도구.',
