      '기본·대문자·하이픈 제거·{중괄호} 네 가지 출력 포맷을 즉시 전환합니다.',
      '개별 복사 외에 "전체 복사" 와 "TXT 다운로드" 로 대량 목록을 한 번에 옮길 수 있습니다.',
