      '구분자를 쉼표(,)·세미콜론(;)·탭(TAB) 중에서 골라 유럽식 CSV 나 TSV 도 처리합니다.',
      '"첫 줄을 헤더로" 옵션으로 헤더 키가 있는 객체 배열 또는 단순 값 배열 중 선택합니다.',
