        body: '구분자(쉼표·세미콜론·탭)를 데이터에 맞게 고릅니다. CSV→JSON 일 때 "첫 줄을 헤더로" 와 "JSON 정렬" 을 켜면 키가 붙은 정렬된 JSON 이 나옵니다.',
