      '인코드는 <·>·&·"·\' 등 HTML 위험 문자를 안전한 엔티티로 바꿔 XSS·태그 깨짐을 막습니다.',
      '디코드는 이름 엔티티(&copy;·&trade;·&hellip;)·10진(&#169;)·16진(&#xa9;) 세 종류를 모두 인식합니다.',
      '"모든 비ASCII 문자도 인코드" 옵션으로 한글·이모지까지 숫자 엔티티(&#NN;)로 변환해 호환성을 높입니다.',
      '입력 즉시 결과가 갱신되고, "방향 바꾸기" 로 결과를 입력으로 보내 연속 변환할 수 있습니다.',
