        q: '압축하면 화질이 많이 떨어지나요?',
        a: 'CRF 와 해상도를 어떻게 잡느냐에 달려 있습니다. CRF 20 전후에 해상도를 유지하면 눈에 띄는 손상 없이도 용량이 꽤 줄어듭니다. CRF 를 30 이상으로 올리거나 480p 로 낮추면 용량은 크게 줄지만 디테일·글자가 뭉개질 수 있습니다. 결과 미리보기로 확인하고, 부족하면 CRF 를 한두 단계 낮춰 다시 시도하세요.',
