      '소문자(26)·대문자(26)·숫자(10)·기호(약 33) 사용 여부로 문자 집합 크기를 추정합니다.',
      '오프라인 대량 추측 공격을 가정한 예상 크래킹 시간을 "약 N년" 처럼 사람이 읽기 쉽게 보여 줍니다.',
      '눈 아이콘으로 입력값을 보이거나 가리며, 강도 막대로 직관적으로 확인합니다.',
      '입력 비밀번호는 메모리에만 존재 — 서버 전송·저장 없이 브라우저에서만 분석합니다.',
