  'rsa-keypair': {
    metaTitle: 'RSA 키페어 생성 (2048·3072·4096비트 PEM) — 무료 온라인',
    metaDescription:
      'Web Crypto API 로 RSA 공개/개인 키페어를 브라우저에서 생성합니다. 2048·3072·4096비트, 서명용(RSA-PSS)·암호화용(RSA-OAEP) 선택, PEM(SPKI·PKCS#8) 출력. 키는 전송되지 않으나 개인 키는 직접 안전하게 보관하세요.',
    intro:
      '브라우저의 Web Crypto API(SubtleCrypto.generateKey)로 RSA 공개/개인 키페어를 만드는 도구입니다. 키 크기(2048·3072·4096비트)와 용도(서명·검증용 RSA-PSS 또는 암호화·복호화용 RSA-OAEP)를 고르면, 공개 키(PEM/SPKI)와 개인 키(PEM/PKCS#8)가 생성됩니다. 모든 생성은 기기 안에서 이뤄지며 키는 서버로 전송되지 않습니다.',
    features: [
      '2048·3072·4096비트 키 크기와 SHA-256 해시로 RSA 키페어를 생성합니다.',
      '용도를 서명·검증(RSA-PSS)과 암호화·복호화(RSA-OAEP) 중에서 선택합니다.',
      '공개 키는 SPKI, 개인 키는 PKCS#8 형식의 PEM(Base64 + 헤더)으로 출력해 OpenSSL·JWT 등에서 바로 씁니다.',
      '각 키를 복사하거나 .pem 파일로 내려받고, "결과 지우기" 로 화면에서 즉시 제거합니다.',
      'Web Crypto API 로 브라우저 안에서 생성 — 키가 네트워크로 전송되지 않습니다.',
    ],
    steps: [
      {
        title: '키 크기·용도 선택',
        body: '"키 크기" 에서 2048(권장)·3072·4096 중 고르고, "용도" 에서 서명·검증(RSA-PSS) 또는 암호화·복호화(RSA-OAEP)를 선택합니다.',
      },
      {
        title: '키페어 생성',
        body: '"키페어 생성" 버튼을 누릅니다. 4096비트는 기기에 따라 5~30초 걸릴 수 있습니다. 완료되면 공개 키와 개인 키가 PEM 으로 나타납니다.',
      },
      {
        title: '저장·보관',
        body: '공개 키는 공유해도 되지만, 개인 키는 .pem 으로 내려받아 안전한 곳에 보관하고 화면의 "결과 지우기" 로 즉시 지우세요. 개인 키는 절대 공개·전송하지 않습니다.',
      },
    ],
    faqs: [
      {
        q: '2048비트와 4096비트 중 무엇을 골라야 하나요?',
        a: '2048비트가 현재 대부분의 용도에 충분하고 생성·연산이 빠릅니다(NIST 권장도 2030년까지 2048비트). 더 긴 보안 수명이나 엄격한 규정이 필요하면 3072·4096비트를 쓰되, 키가 길수록 생성과 서명·암호화 연산이 느려진다는 점을 감안하세요.',
      },
      {
        q: '생성한 개인 키는 안전한가요?',
        a: '키 생성은 브라우저 안에서만 이뤄지고 어디로도 전송되지 않습니다. 다만 개인 키가 화면·클립보드에 남으므로, .pem 으로 저장해 안전한 곳에 두고 작업 후 "결과 지우기" 로 화면에서 지우는 것이 좋습니다. 공용 PC 에서는 특히 주의하세요.',
      },
      {
        q: '서명용과 암호화용은 무엇이 다른가요?',
        a: '서명·검증(RSA-PSS)은 데이터가 위조되지 않았음을 증명하는 디지털 서명에, 암호화·복호화(RSA-OAEP)는 공개 키로 암호화하고 개인 키로 푸는 비밀 전송에 씁니다. 용도에 맞지 않는 키는 해당 작업에 쓸 수 없으니 목적에 맞게 선택하세요.',
      },
    ],
  },

