      'Markdown → HTML 결과를 렌더된 미리보기와 HTML 소스로 토글해 확인합니다(미리보기는 DOMPurify 로 안전하게 정화).',
      '결과를 복사하거나 converted.html / converted.md 파일로 내려받습니다.',
