      '객체는 모든 키를 properties 에 넣고 required 에도 모두 올려, 샘플에 있는 키를 전부 필수로 간주합니다.',
      '배열은 요소 스키마를 병합합니다 — 요소가 모두 같으면 단일 items 로, 서로 다르면 items.anyOf 로 표현합니다.',
