      '문자별로 글리프·코드포인트(U+XXXX)·추정 이름·UTF-8 바이트열(16진)·10진 HTML 엔티티(&#NNN;)를 열로 보여 줍니다.',
      '이름 추정은 C0/C1 제어문자·SPACE·숫자·라틴 문자·한글 음절/자모·CJK·히라가나·가타카나·이모지/기호·일반 구두점 범위를 다룹니다.',
      'UTF-8 바이트는 TextEncoder 로 계산하고, 공백 같은 보이지 않는 글리프는 표에서 눈에 보이는 자리표시자로 나타냅니다.',
      '총 글자 수를 표시하고 "표 복사" 버튼으로 행을 TSV(탭 구분)로 내보낼 수 있으며, 모든 처리는 브라우저 안에서 이뤄집니다.',
