      '세금 = 기본금액 × 세율, 팁 = 기본금액 × 팁율(팁은 세전 금액 기준), 총액 = 기본금액 + 세금 + 팁.',
      '1인당 = 총액 / 인원수, 금액은 반올림 후 천 단위 구분 기호가 붙은 ₩ 로 표시됩니다.',
