  'ideal-weight': {
    metaTitle: '적정 체중 계산기 (Devine·Robinson·BMI 22) — 무료',
    metaDescription:
      '키와 성별로 적정 체중을 Devine·Robinson·BMI 22 공식으로 추정하고 정상 BMI 범위를 보여 줍니다. 170cm 남성이면 세 공식 값과 18.5~24.9 BMI 구간을 함께 내주는 무료 적정 체중 계산기.',
    intro:
      '키와 성별로 적정 체중을 여러 공식으로 추정하고 건강 BMI 범위까지 함께 보여 주는 도구입니다. Devine·Robinson 공식과 BMI 22 기준값을 동시에 계산합니다. 예를 들어 170cm 남성을 넣으면 세 공식의 적정 체중과 18.5~24.9 BMI 구간이 함께 나옵니다. 어디까지나 추정치 참고용입니다.',
    features: [
      'Devine(1974): 남성 50 / 여성 45.5kg 기본 + 152.4cm(60인치) 초과 1인치당 2.3kg.',
      'Robinson(1983): 남성 52 / 여성 49kg 기본 + 60인치 초과 1인치당 남성 1.9 / 여성 1.7kg.',
      'BMI 22 기준(성별 무관): 체중 = 22 × 키(m)².',
      '건강 BMI 범위는 18.5 × m² 부터 24.9 × m² 까지로 계산하며 결과는 kg 소수 첫째 자리로 보여 줍니다.',
      '키 입력은 100~250cm 로 제한하고 남/여 토글을 제공하며, 복사 버튼이 있고 추정 참고용으로 브라우저 안에서 동작합니다.',
    ],
    steps: [
      {
        title: '키 입력',
        body: '키를 cm 로 넣습니다(100~250 범위).',
      },
      {
        title: '성별 선택',
        body: '남성·여성을 골라 Devine·Robinson 기본값을 조정합니다.',
      },
      {
        title: '결과 비교',
        body: 'Devine·Robinson·BMI 22 체중과 정상 BMI 범위를 비교한 뒤 복사합니다. 체중과 키로 BMI 자체가 궁금하면 [BMI 계산기](guide:bmi-calc)를 쓰세요.',
      },
    ],
    faqs: [
      {
        q: '어느 공식이 가장 믿을 만한가요?',
        a: '모두 추정치입니다. Devine 는 임상(예: 약물 용량 계산)에서 널리 쓰이고, Robinson 은 이를 보정한 변형이며, BMI 22 는 건강 BMI 중간값을 반영합니다. 셋을 비교하면 하나의 "정답" 이 아니라 적정 범위를 가늠할 수 있습니다.',
      },
      {
        q: '남성과 여성의 값이 다른 이유는요?',
        a: 'Devine·Robinson 공식이 성별에 따라 다른 기본 체중과 1인치당 증가량을 쓰기 때문입니다. BMI 22 값만 성별과 무관합니다.',
      },
      {
        q: '이 결과가 건강 권고인가요?',
        a: '아니요. 참고용 추정치이며 도구도 그렇게 표시합니다. 맥락을 위해 정상 BMI(18.5~24.9) 구간을 함께 보여 줄 뿐입니다.',
      },
    ],
  },

