      '모음 규칙 — 모음으로 시작하는 단어에 way(apple → appleway) 또는 yay(apple → appleyay) 중 고른 접미사를 붙입니다.',
      '단어 첫 글자의 대소문자를 결과에서도 그대로 유지합니다.',
