      'border 트릭으로 동작합니다 — width:0/height:0에 반대편 border만 색칠하고 양옆 border는 투명으로 둡니다(예: 위 방향 = border-bottom에 색).',
      '대각선 4방향은 인접한 두 border 중 하나만 색칠해 직각삼각형으로 만듭니다.',
      'width:0/height:0 + border 선언으로 된 CSS 코드를 복사 버튼으로 가져갈 수 있습니다.',
